import heapq

def match(orders):
    trades = []
    order_info = {}  # id -> dict with side, price, qty, active, seq
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def peek(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return top
        return None

    for order in orders:
        kind = order[0]
        if kind == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if kind == 'limit':
            _, oid, side, price, qty = order
        elif kind == 'ioc':
            _, oid, side, price, qty = order
        elif kind == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = peek(sell_heap)
                if top is None:
                    break
                resting_price = top[0]
                if price is not None and resting_price > price:
                    break
                resting_id = top[2]
                resting_info = order_info[resting_id]
                trade_qty = min(remaining, resting_info['qty'])
                trades.append([oid, resting_id, resting_price, trade_qty])
                remaining -= trade_qty
                resting_info['qty'] -= trade_qty
                if resting_info['qty'] == 0:
                    resting_info['active'] = False
                    heapq.heappop(sell_heap)
        else:  # sell
            while remaining > 0:
                top = peek(buy_heap)
                if top is None:
                    break
                resting_price = -top[0]
                if price is not None and resting_price < price:
                    break
                resting_id = top[2]
                resting_info = order_info[resting_id]
                trade_qty = min(remaining, resting_info['qty'])
                trades.append([resting_id, oid, resting_price, trade_qty])
                remaining -= trade_qty
                resting_info['qty'] -= trade_qty
                if resting_info['qty'] == 0:
                    resting_info['active'] = False
                    heapq.heappop(buy_heap)

        if kind == 'limit' and remaining > 0:
            order_info[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'active': True,
                'seq': seq
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            # ioc/market remainder discarded, or limit fully filled
            if kind == 'limit':
                order_info[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'active': False,
                    'seq': seq
                }
            else:
                order_info[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'active': False,
                    'seq': seq
                }

    return trades

